List<CwaStation>? _stations;
List<CwaTownship>? _townships;

/// The 363 bundled observation stations, parsed on first use.
List<CwaStation> get cwaStations {
  return _stations ??= _stationTable
      .split(';')
      .where((entry) => entry.isNotEmpty)
      .map((entry) {
        final parts = entry.split(',');
        return CwaStation(
          id: parts[0],
          latitude: double.parse(parts[1]),
          longitude: double.parse(parts[2]),
          county: parts[3],
        );
      })
      .toList(growable: false);
}

/// The 368 bundled forecast townships, parsed on first use.
List<CwaTownship> get cwaTownships {
  return _townships ??= _townshipTable
      .split(';')
      .where((entry) => entry.isNotEmpty)
      .map((entry) {
        final parts = entry.split(',');
        return CwaTownship(
          county: parts[0],
          name: parts[1],
          latitude: double.parse(parts[2]),
          longitude: double.parse(parts[3]),
        );
      })
      .toList(growable: false);
}
